{
  "requirement_id": "REQ-003",
  "summary": "Implement pagination for the project task list API (GET /api/projects/{pid}/tasks) with limit, offset, and sorting by task id ascending, including validation and metadata response.",
  "acceptance_criteria": [
    "limit defaults to 20, with a valid range of 1 to 100; offset defaults to 0 and must be greater than or equal to 0; out-of-range values return 422.",
    "total represents the total number of matching tasks, unaffected by pagination.",
    "Iterating through pages from offset=0 with a fixed limit to the end must yield the exact set of all tasks without duplication or omission.",
    "When offset is greater than or equal to total, items must be an empty array."
  ]
}

