{"cases": [
  {
    "id": "TC-1",
    "title": "Verify limit and offset boundary validation rules",
    "surface": "api",
    "steps": [
      "GET /api/projects/1/tasks?limit=0",
      "GET /api/projects/1/tasks?limit=101",
      "GET /api/projects/1/tasks?offset=-1"
    ],
    "expected": "limit defaults to 20, with a valid range of 1 to 100; offset defaults to 0 and must be greater than or equal to 0; out-of-range values return 422."
  },
  {
    "id": "TC-2",
    "title": "Verify default limit and offset values when parameters are omitted",
    "surface": "api",
    "steps": [
      "GET /api/projects/1/tasks"
    ],
    "expected": "limit defaults to 20, with a valid range of 1 to 100; offset defaults to 0 and must be greater than or equal to 0; out-of-range values return 422."
  },
  {
    "id": "TC-3",
    "title": "Verify total represents the total number of matching tasks unaffected by pagination",
    "surface": "api",
    "steps": [
      "GET /api/projects/1/tasks?limit=1&offset=0",
      "GET /api/projects/1/tasks?limit=1&offset=1"
    ],
    "expected": "total represents the total number of matching tasks, unaffected by pagination."
  },
  {
    "id": "TC-4",
    "title": "Verify iterating through pages yields the exact set of all tasks without duplication or omission",
    "surface": "api",
    "steps": [
      "GET /api/projects/1/tasks?limit=2&offset=0",
      "GET /api/projects/1/tasks?limit=2&offset=2"
    ],
    "expected": "Iterating through pages from offset=0 with a fixed limit to the end must yield the exact set of all tasks without duplication or omission."
  },
  {
    "id": "TC-5",
    "title": "Verify items is an empty array when offset is greater than or equal to total",
    "surface": "api",
    "steps": [
      "GET /api/projects/1/tasks?offset=999"
    ],
    "expected": "When offset is greater than or equal to total, items must be an empty array."
  }
]}

